  public static int GetNextSlot()
  {
    int nextSlot = 1000;
    for (int index = 0; index < 1000; ++index)
    {
      if (!Main.projectile[index].active)
      {
        nextSlot = index;
        break;
      }
    }
    return nextSlot;
  }

  public static int NewProjectile(
    IEntitySource spawnSource,
    Vector2 position,
    Vector2 velocity,
    int Type,
    int Damage,
    float KnockBack,
    int Owner = -1,
    float ai0 = 0.0f,
    float ai1 = 0.0f,
    float ai2 = 0.0f,
    NewProjectileModifier modifer = null)
  {
    return Projectile.NewProjectile(spawnSource, position.X, position.Y, velocity.X, velocity.Y, Type, Damage, KnockBack, Owner, ai0, ai1, ai2, modifer);
  }

  public static int FindOldestProjectile()
  {
    int oldestProjectile = 1000;
    int num = 9999999;
    for (int index = 0; index < 1000; ++index)
    {
      if (!Main.projectile[index].netImportant && Main.projectile[index].timeLeft < num)
      {
        oldestProjectile = index;
        num = Main.projectile[index].timeLeft;
      }
    }
    return oldestProjectile;
  }

  public static int NewProjectile(
    IEntitySource spawnSource,
    float X,
    float Y,
    float SpeedX,
    float SpeedY,
    int Type,
    int Damage,
    float KnockBack,
    int Owner = -1,
    float ai0 = 0.0f,
    float ai1 = 0.0f,
    float ai2 = 0.0f,
    NewProjectileModifier modifer = null)
  {
    if (Owner == -1)
      Owner = (int) byte.MaxValue;
    int number = 1000;
    for (int index = 0; index < 1000; ++index)
    {
      if (!Main.projectile[index].active)
      {
        number = index;
        break;
      }
    }
    if (number == 1000)
      number = Projectile.FindOldestProjectile();
    Projectile projectile = Main.projectile[number];
    if (Main.NoPooling)
      projectile = Main.projectile[number] = new Projectile();
    projectile.SetDefaults(Type);
    projectile.whoAmI = number;
    projectile.position.X = X - (float) projectile.width * 0.5f;
    projectile.position.Y = Y - (float) projectile.height * 0.5f;
    projectile.owner = Owner;
    projectile.velocity.X = SpeedX;
    projectile.velocity.Y = SpeedY;
    projectile.damage = Damage;
    projectile.knockBack = KnockBack;
    projectile.identity = number;
    projectile.gfxOffY = 0.0f;
    projectile.stepSpeed = 1f;
    projectile.wet = Collision.WetCollision(projectile.position, projectile.width, projectile.height);
    if (projectile.ignoreWater)
      projectile.wet = false;
    projectile.honeyWet = Collision.honey;
    projectile.shimmerWet = Collision.shimmer;
    Main.projectileIdentity[Owner, number] = number;
    projectile.ApplyStatsFromSource(spawnSource);
    projectile.FindBannerToAssociateTo(spawnSource);
    projectile.TrackMinionSpawnSource(spawnSource);
    if (projectile.aiStyle == 1)
    {
      for (; (double) projectile.velocity.X >= 16.0 || (double) projectile.velocity.X <= -16.0 || (double) projectile.velocity.Y >= 16.0 || (double) projectile.velocity.Y < -16.0; projectile.velocity.Y *= 0.97f)
        projectile.velocity.X *= 0.97f;
    }
    if (Owner == Main.myPlayer)
    {
      switch (Type)
      {
        case 206:
          projectile.ai[0] = (float) Main.rand.Next(-100, 101) * 0.0005f;
          projectile.ai[1] = (float) Main.rand.Next(-100, 101) * 0.0005f;
          break;
        case 335:
          projectile.ai[1] = (float) Main.rand.Next(4);
          break;
        case 358:
          projectile.ai[1] = (float) Main.rand.Next(10, 31 /*0x1F*/) * 0.1f;
          break;
        case 406:
          projectile.ai[1] = (float) Main.rand.Next(10, 21) * 0.1f;
          break;
        default:
          projectile.ai[0] = ai0;
          projectile.ai[1] = ai1;
          projectile.ai[2] = ai2;
          break;
      }
    }
    if (Type == 434)
    {
      projectile.ai[0] = projectile.position.X;
      projectile.ai[1] = projectile.position.Y;
    }
    if (Type > 0 && Type < (int) ProjectileID.Count)
    {
      if (ProjectileID.Sets.NeedsUUID[Type])
        projectile.projUUID = projectile.identity;
      if (ProjectileID.Sets.StardustDragon[Type])
      {
        int projUuid = Main.projectile[(int) projectile.ai[0]].projUUID;
        if (projUuid >= 0)
          projectile.ai[0] = (float) projUuid;
      }
    }
    if (Owner == Main.myPlayer)
    {
      if (ProjectileID.Sets.IsAGolfBall[Type] && Damage <= 0)
      {
        int num1 = 0;
        int index1 = 0;
        int num2 = 99999999;
        for (int index2 = 0; index2 < 1000; ++index2)
        {
          if (Main.projectile[index2].active && ProjectileID.Sets.IsAGolfBall[Main.projectile[index2].type] && Main.projectile[index2].owner == Owner && Main.projectile[index2].damage <= 0)
          {
            ++num1;
            if (num2 > Main.projectile[index2].timeLeft)
            {
              index1 = index2;
              num2 = Main.projectile[index2].timeLeft;
            }
          }
        }
        if (num1 > 10)
          Main.projectile[index1].Kill();
      }
      if (ProjectileID.Sets.CopiesOwnerAttackCDToLocalImmunityOnSpawn[Type])
      {
        int[] meleeNpcHitCooldown = Main.player[Owner].meleeNPCHitCooldown;
        int[] localNpcImmunity = projectile.localNPCImmunity;
        for (int index = 0; index < Main.maxNPCs; ++index)
        {
          int num = meleeNpcHitCooldown[index];
          if (num > 0)
            localNpcImmunity[index] = num;
        }
      }
      if (Type == 28)
        projectile.timeLeft = 180;
      if (Type == 1077)
        projectile.timeLeft = 180;
      if (Type == 516)
        projectile.timeLeft = 180;
      if (Type == 519)
        projectile.timeLeft = 180;
      if (Type == 1086 || Type == 1087)
        projectile.timeLeft = 300;
      if (Type == 29 || Type == 470 || Type == 637)
        projectile.timeLeft = 300;
      if (Type == 30)
        projectile.timeLeft = 180;
      if (Type == 517)
        projectile.timeLeft = 180;
