      if (Type == 421)
        projectile.timeLeft = 600;
      if (Type == 422)
        projectile.timeLeft = 600;
      if (Type == 588)
        projectile.timeLeft = 180;
      if (Type == 779)
        projectile.timeLeft = 60;
      if (Type == 783)
        projectile.timeLeft = 60;
      if (Type == 862 || Type == 863)
        projectile.timeLeft = 60;
      if (Type == 443 || Type == 1110)
        projectile.timeLeft = 300;
      if (Type == 681)
        projectile.timeLeft = 600;
      if (Type == 684)
        projectile.timeLeft = 60;
      if (Type == 706)
        projectile.timeLeft = 120;
      if (Type == 680 && Main.player[projectile.owner].setSquireT2)
        projectile.penetrate = 7;
      if (Type == 777 || Type == 781 || Type == 794 || Type == 797 || Type == 800 || Type == 785 || Type == 788 || Type == 791 || Type == 903 || Type == 904 || Type == 905 || Type == 906 || Type == 910 || Type == 911)
        projectile.timeLeft = 180;
    }
    if (Type == 249)
      projectile.frame = Main.rand.Next(5);
    if (modifer != null)
      modifer(projectile);
    if (Main.netMode != 0 && Owner == Main.myPlayer)
      NetMessage.SendData(27, number: number);
    if (Owner == Main.myPlayer)
      Main.player[Owner].TryUpdateChannel(projectile);
    return number;
  }

  private void FindBannerToAssociateTo(IEntitySource spawnSource)
  {
    if (!(spawnSource is EntitySource_Parent entitySourceParent))
      return;
    if (entitySourceParent.Entity is Projectile entity1)
    {
      this.bannerIdToRespondTo = entity1.bannerIdToRespondTo;
    }
    else
    {
      if (!(entitySourceParent.Entity is NPC entity))
        return;
      this.bannerIdToRespondTo = BannerSystem.NPCtoBanner(entity.BannerID());
    }
  }

  private void ApplyStatsFromSource(IEntitySource spawnSource)
  {
    if (spawnSource is EntitySource_ItemUse entitySourceItemUse)
    {
      Item obj = entitySourceItemUse.Item;
      if (ItemID.Sets.UniqueTagEffects[obj.type] != null)
        this.tagEffectType = obj.type;
      this.bonusTagDamage += obj.bonusTagDamage;
      this.armorPenetration += obj.armorPenetration;
      if (obj.type == 2269 && entitySourceItemUse.Entity is Player)
        this.bonusCritChance += ((Player) entitySourceItemUse.Entity).revolverCritChanceBonus;
    }
    if (!(spawnSource is EntitySource_Parent entitySourceParent) || !(entitySourceParent.Entity is Projectile entity))
      return;
    this.tagEffectType = entity.tagEffectType;
    this.bonusTagDamage += entity.bonusTagDamage;
    this.armorPenetration += entity.armorPenetration;
    this.bonusCritChance += entity.bonusCritChance;
  }

  private void TrackMinionSpawnSource(IEntitySource spawnSource)
  {
    if (!this.minion || !ProjectileID.Sets.TrackMinionSpawnFromItemUse[this.type] || !(spawnSource is EntitySource_ItemUse entitySourceItemUse))
      return;
    this.MinionSpawnInfo = (MinionSpawnInfo) new MinionSpawnFromInventoryItem(entitySourceItemUse.Item);
  }

  public static Color GetGolfTrailColor(Projectile proj)
  {
    switch (proj.type)
    {
      case 739:
        return new Color(50, 50, 50, 80 /*0x50*/);
      case 740:
        return new Color(30, 50, (int) byte.MaxValue, 40);
      case 741:
        return new Color(150, 90, 60, 90);
      case 742:
        return new Color(30, (int) byte.MaxValue, 170, 30);
      case 743:
        return new Color(30, (int) byte.MaxValue, 30, 40);
      case 744:
        return new Color(190, (int) byte.MaxValue, 30, 50);
      case 745:
        return new Color((int) byte.MaxValue, 130, 30, 50);
      case 746:
        return new Color((int) byte.MaxValue, 50, 110, 50);
      case 747:
        return new Color(130, 10, 200, 40);
      case 748:
        return new Color((int) byte.MaxValue, 30, 50, 50);
      case 749:
        return new Color(100, 180, (int) byte.MaxValue, 30);
      case 750:
        return new Color(50, 240 /*0xF0*/, 160 /*0xA0*/, 30);
      case 751:
        return new Color(220, 80 /*0x50*/, 220, 70);
      case 752:
        return new Color((int) byte.MaxValue, 180, 50, 30);
      default:
        return new Color(160 /*0xA0*/, 160 /*0xA0*/, (int) byte.MaxValue, 50);
    }
  }

