          break;
        case 22:
          damageMultiplier = 2f;
          break;
        case 23:
          damageMultiplier = 1.9f;
          break;
      }
    }
    if (this.type == 533 && (double) this.localAI[2] >= 40.0)
      damageMultiplier *= 0.5f;
