  private void Damage_PVP(Microsoft.Xna.Framework.Rectangle projRectangle, float projectileSpecificDamageMultiplier)
  {
    if (this.damage <= 0 || !Main.player[Main.myPlayer].hostile)
      return;
    for (int index = 0; index < (int) byte.MaxValue; ++index)
    {
      if (index != this.owner)
      {
