  private void Damage_EVP(Microsoft.Xna.Framework.Rectangle projRectangle)
  {
    if (!this.hostile || Main.myPlayer >= (int) byte.MaxValue || this.damage <= 0)
      return;
    int cooldownCounter = ImmunityCooldownID.General;
    switch (this.type)
    {
      case 452:
      case 454:
      case 455:
      case 462:
        cooldownCounter = ImmunityCooldownID.BossNoCheese;
        break;
      case 871:
      case 872:
      case 873:
      case 874:
      case 919:
      case 923:
      case 924:
        cooldownCounter = ImmunityCooldownID.BossNoCheese;
        break;
    }
    int player = Main.myPlayer;
    bool flag = Main.player[player].active && !Main.player[player].dead && (!Main.player[player].immune || cooldownCounter != ImmunityCooldownID.General);
    if (flag && this.type == 281)
      flag = (double) this.ai[1] - 1.0 == (double) player;
    if (Main.getGoodWorld && this.type == 281)
      flag = true;
    if (this.type == 1073 && Main.player[player].npcTypeNoAggro[1])
      flag = false;
    if (this.type == 1078 && Main.player[player].spaceGun)
      flag = false;
    if (!flag || !this.Colliding(projRectangle, Main.player[player].getRect()))
      return;
    int direction = this.direction;
    int hitDirection = (double) Main.player[player].position.X + (double) (Main.player[player].width / 2) >= (double) this.position.X + (double) (this.width / 2) ? 1 : -1;
    if (!Main.player[player].CanParryAgainst(Main.player[player].Hitbox, this.Hitbox, this.velocity))
    {
      this.SpawnHitVisuals((Entity) Main.player[player]);
      this.TryDoingOnHitEffects((Entity) Main.player[player]);
      int num1 = Main.DamageVar((float) this.damage, -Main.player[this.owner].luck);
      ItemID.BannerEffect effect;
      if (Main.player[player].GetBannerBuffEffect(this.bannerIdToRespondTo, out effect))
        num1 = (int) ((double) num1 * (double) effect.DamageReceived.Sample(Main.Difficulty));
      if (Main.player[player].resistCold && this.coldDamage)
        num1 = (int) ((double) num1 * 0.699999988079071);
      if (!this.reflected)
        num1 = (int) ((double) num1 * (double) this.hostileDamageScaling.Sample(Main.Difficulty));
      int num2 = 2;
      int num3 = num1 * num2;
      if (Main.player[player].deadMansSweater && this.trap)
        num3 = Math.Min((int) ((double) num3 * 0.5), 300);
      int Damage = num3;
      if (this.type == 961)
      {
        if (this.penetrate == 1)
        {
          this.damage = 0;
          this.penetrate = -1;
        }
        else
          this.damage = (int) ((double) this.damage * 0.7);
      }
      bool dodgeable = this.IsDamageDodgable();
      int playerIndex = -1;
      if (ProjectileID.Sets.IsAGravestone[this.type])
        playerIndex = (int) this.ai[0];
      if (Main.player[player].Hurt(PlayerDeathReason.ByProjectile(playerIndex, this.whoAmI), Damage, hitDirection, cooldownCounter: cooldownCounter, dodgeable: dodgeable) > 0.0 && !Main.player[player].dead)
        this.StatusPlayer(Main.player[player]);
      if (this.trap)
      {
        Main.player[player].trapDebuffSource = true;
        if (Main.player[player].dead)
          AchievementsHelper.HandleSpecialEvent(Main.player[player], 4);
      }
    }
    if (false)
      return;
    if (this.type == 435 || this.type == 682)
      --this.penetrate;
    if (this.type == 436)
      --this.penetrate;
    if (this.type == 681)
      this.timeLeft = 0;
    if (this.type != 437)
      return;
    --this.penetrate;
  }

