  private void RecheckSectionsForSkippedUpdates()
  {
    bool[] skippedForPlayer = this.netSyncSkippedForPlayer;
    for (int remoteClient = 0; remoteClient < skippedForPlayer.Length; ++remoteClient)
    {
      if (skippedForPlayer[remoteClient] && Main.player[remoteClient].active && Netplay.Clients[remoteClient].IsSectionActive(this.NetSectionCoordinates))
        NetMessage.SendData(27, remoteClient, number: this.whoAmI);
    }
  }

  public void DecrementLocalImmuneTimeCounters()
  {
    for (int index = 0; index < (int) byte.MaxValue; ++index)
    {
      if (this.playerImmune[index] > 0)
        --this.playerImmune[index];
    }
    if (!this.usesLocalNPCImmunity)
      return;
    for (int index = 0; index < Main.maxNPCs; ++index)
    {
      if (this.localNPCImmunity[index] > 0)
        --this.localNPCImmunity[index];
    }
  }

