      if (Main.rand.Next(2) == 0)
        Main.dust[index].scale = 1.5f;
      Main.dust[index].noGravity = true;
      Main.dust[index].velocity.X *= 2f;
      Main.dust[index].velocity.Y *= 2f;
    }
    if (player.mount.Active && (player.mount.Type == 62 || player.mount.Type == 63 /*0x3F*/) && (this.melee || this.ranged) && this.friendly && !this.hostile && !this.noEnchantments)
    {
      Vector3 vector3 = player.mount.Type == 63 /*0x3F*/ ? new Vector3(0.6f, 0.3f, 0.1f) : new Vector3(0.5f, 0.1f, 0.6f);
      Lighting.AddLight(boxPosition + new Vector2((float) boxWidth / 2f, (float) boxHeight / 2f), vector3 * 0.5f);
