  private void FishingCheck_ProbeForQuestFish(ref FishingAttempt fisher)
  {
    fisher.questFish = Main.anglerQuestItemNetIDs[Main.anglerQuest];
    if (Main.player[this.owner].HasItem(fisher.questFish))
      fisher.questFish = -1;
    if (!NPC.AnyNPCs(369))
      fisher.questFish = -1;
    if (!Main.anglerQuestFinished)
      return;
    fisher.questFish = -1;
  }

  private void FishingCheck_RollDropLevels(
    int fishingLevel,
    out bool common,
    out bool uncommon,
    out bool rare,
    out bool veryrare,
    out bool legendary,
    out bool crate)
  {
    int num1 = 150;
    int maxValue1 = num1 / fishingLevel;
    int maxValue2 = num1 * 2 / fishingLevel;
    int maxValue3 = num1 * 7 / fishingLevel;
    int maxValue4 = num1 * 15 / fishingLevel;
    int maxValue5 = num1 * 30 / fishingLevel;
    int num2 = 10;
    if (Main.player[this.owner].cratePotion)
      num2 += 15;
    if (maxValue1 < 2)
      maxValue1 = 2;
    if (maxValue2 < 3)
      maxValue2 = 3;
    if (maxValue3 < 4)
      maxValue3 = 4;
    if (maxValue4 < 5)
      maxValue4 = 5;
    if (maxValue5 < 6)
      maxValue5 = 6;
    common = false;
    uncommon = false;
    rare = false;
    veryrare = false;
    legendary = false;
    crate = false;
    if (Main.rand.Next(maxValue1) == 0)
      common = true;
    if (Main.rand.Next(maxValue2) == 0)
      uncommon = true;
    if (Main.rand.Next(maxValue3) == 0)
      rare = true;
    if (Main.rand.Next(maxValue4) == 0)
      veryrare = true;
    if (Main.rand.Next(maxValue5) == 0)
      legendary = true;
    if (Main.rand.Next(100) >= num2)
      return;
    crate = true;
  }

  private static void GetFishingPondState(
    int x,
    int y,
    out bool lava,
    out bool honey,
    out int numWaters,
    out int chumCount)
  {
    lava = false;
    honey = false;
    numWaters = 0;
    chumCount = 0;
    Point tileCoords = new Point(0, 0);
    int minX;
    int maxX;
    Projectile.GetFishingPondWidth(x, y, out minX, out maxX);
    for (int i = minX; i <= maxX; ++i)
    {
      for (int j = y; Main.tile[i, j] != null && Main.tile[i, j].liquid > (byte) 0 && !WorldGen.SolidTile(i, j) && j < Main.maxTilesY - 10; ++j)
      {
        ++numWaters;
        if (Main.tile[i, j].lava())
          lava = true;
        else if (Main.tile[i, j].honey())
          honey = true;
        tileCoords.X = i;
        tileCoords.Y = j;
        chumCount += Main.instance.ChumBucketProjectileHelper.GetChumsInLocation(tileCoords);
      }
    }
    if (!honey)
      return;
    numWaters = (int) ((double) numWaters * 1.5);
  }

  private static void GetFishingPondWidth(int x, int y, out int minX, out int maxX)
  {
    minX = x;
    maxX = x;
    while (minX > 10 && Main.tile[minX, y] != null && Main.tile[minX, y].liquid > (byte) 0 && !WorldGen.SolidTile(minX, y))
      --minX;
    while (maxX < Main.maxTilesX - 10 && Main.tile[maxX, y] != null && Main.tile[maxX, y].liquid > (byte) 0 && !WorldGen.SolidTile(maxX, y))
      ++maxX;
  }

  public bool CanBeReflected()
  {
    return this.active && this.friendly && !this.hostile && this.damage > 0 && (this.type == 728 || this.type == 955 || this.aiStyle == 1 || this.aiStyle == 2 || this.aiStyle == 8 || this.aiStyle == 21 || this.aiStyle == 24 || this.aiStyle == 28 || this.aiStyle == 29 || this.aiStyle == 131);
  }

  public Color GetConstellationColor(
    float alphaChannelMultiplier = 1f,
    float lerpToWhite = 0.0f,
    float? rawHueOverride = null)
  {
    float num1 = this.ai[1];
    if (rawHueOverride.HasValue)
      num1 = rawHueOverride.Value;
    double Hue = ((double) num1 + 0.5) % 1.0;
    float num2 = 1f;
    float num3 = 0.5f;
    double Saturation = (double) num2;
    double Luminosity = (double) num3;
    Color constellationColor = Main.hslToRgb((float) Hue, (float) Saturation, (float) Luminosity) * this.Opacity;
    if ((double) lerpToWhite != 0.0)
      constellationColor = Color.Lerp(constellationColor, Color.White, lerpToWhite);
    constellationColor.A = (byte) ((double) constellationColor.A * (double) alphaChannelMultiplier);
    return constellationColor;
  }

  public Color GetFairyQueenWeaponsColor(
    float alphaChannelMultiplier = 1f,
    float lerpToWhite = 0.0f,
