  public bool AI_053_HandleSentryNPCTargeting(
    Vector2 firingOffset,
    bool straightLine,
    out int targetSlot,
    out float x,
    out float y,
    float maxDistance = 1000f)
  {
    bool flag = false;
    Vector2 Position1 = this.Center + firingOffset;
    x = Position1.X;
    y = Position1.Y;
    targetSlot = -1;
    NPC minionAttackTargetNpc = this.OwnerMinionAttackTargetNPC;
    if (minionAttackTargetNpc != null && minionAttackTargetNpc.CanBeChasedBy((object) this))
    {
      Vector2 center = minionAttackTargetNpc.Center;
      float num = Math.Abs(x - center.X) + Math.Abs(y - center.Y);
      if ((double) num < (double) maxDistance)
      {
        if (!straightLine ? Collision.CanHit(Position1, 0, 0, center, 0, 0) : Collision.CanHitLine(Position1, 0, 0, center, 0, 0))
        {
          maxDistance = num;
          x = center.X;
          y = center.Y;
          flag = true;
          targetSlot = minionAttackTargetNpc.whoAmI;
        }
      }
    }
    if (!flag)
    {
      for (int index = 0; index < Main.maxNPCs; ++index)
      {
        if (Main.npc[index].CanBeChasedBy((object) this))
        {
          Vector2 center = Main.npc[index].Center;
          float num = Math.Abs(Position1.X - center.X) + Math.Abs(Position1.Y - center.Y);
          if ((double) num < (double) maxDistance)
          {
            if (!straightLine ? Collision.CanHit(Position1, 0, 0, center, 0, 0) : Collision.CanHitLine(Position1, 0, 0, center, 0, 0))
            {
              maxDistance = num;
              x = center.X;
              y = center.Y;
              flag = true;
              targetSlot = Main.npc[index].whoAmI;
            }
          }
        }
      }
    }
    return flag;
  }

