      Vector2 center = playerArmPosition;
      Vector2 vector2_8 = spinningpoint.RotatedBy(radians, center);
      controlPoints.Add(vector2_8);
      f1 += num11;
      f3 += num11;
      f2 += num11;
      vector2_1 = vector2_4;
