  public static void GetWhipSettings(
    Projectile proj,
    out float timeToFlyOut,
    out int segments,
    out float rangeMultiplier)
  {
    timeToFlyOut = (float) (Main.player[proj.owner].itemAnimationMax * proj.MaxUpdates);
