        segments = 40;
        rangeMultiplier = 1.6f;
        break;
      case 849:
        segments = 30;
        rangeMultiplier = 2.15f;
        break;
      case 912:
        rangeMultiplier *= 1.5f;
        break;
      case 913:
        rangeMultiplier *= 1.4f;
        break;
      case 914:
        rangeMultiplier *= 1f;
        break;
