      case 1029:
        rangeMultiplier *= 0.95f;
        break;
      case 1030:
        rangeMultiplier *= 0.85f;
        break;
      case 1031:
        rangeMultiplier *= 1.1f;
        break;
      case 1032:
        rangeMultiplier *= 1.8f;
        break;
      case 1033:
