  private void FindBlockSurface(int x, ref int y, int downMax, int upmax)
  {
    for (int index = 0; index < downMax && y >= 10 && WorldGen.SolidTile(x, y); ++index)
      --y;
    for (int index = 0; index < upmax && y <= Main.maxTilesY - 10 && !WorldGen.ActiveAndWalkableTile(x, y); ++index)
      ++y;
  }

  private void FindBlockCeiling(int x, ref int y, int upMax, int downMax)
  {
    for (int index = 0; index < upMax && y <= Main.maxTilesY - 10 && WorldGen.SolidTile(x, y); ++index)
      ++y;
    for (int index = 0; index < downMax && y >= 10 && !WorldGen.ActiveAndWalkableTile(x, y); ++index)
      --y;
  }

