      Main.tile[X, Y - 1] = new Tile();
    if (Main.tile[X, Y] == null)
      Main.tile[X, Y] = new Tile();
    if (Main.tile[X, Y + 1] == null)
      Main.tile[X, Y + 1] = new Tile();
    if (Main.tile[X, Y - 1].liquid > (byte) 0)
      waterLine = (float) (Y * 16 /*0x10*/) - (float) ((int) Main.tile[X, Y - 1].liquid / 16 /*0x10*/);
    else if (Main.tile[X, Y].liquid > (byte) 0)
      waterLine = (float) ((Y + 1) * 16 /*0x10*/) - (float) ((int) Main.tile[X, Y].liquid / 16 /*0x10*/);
    else if (Main.tile[X, Y + 1].liquid > (byte) 0)
      waterLine = (float) ((Y + 2) * 16 /*0x10*/) - (float) ((int) Main.tile[X, Y + 1].liquid / 16 /*0x10*/);
